INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(42211, 'Job 33:26', 'Job', 33, 26, 'بيا هغه خُدائ پاک ته سوال وکړى او سوال يې قبول شى، هغه په خوشحالۍ سره د خُدائ پاک حضور ته راشى، او هغه يې بيا يو نېک سړے جوړ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_26.mp3', '', 1761754199, 1761754199),
(42212, 'Job 33:27', 'Job', 33, 27, 'هغه به نورو کسانو ته وائى چې، ما ګناه کړې ده، او د نېکۍ په ځائ مې بدى کړې ده. او خُدائ پاک ما له د هغې سزا نۀ ده راکړې د څۀ چې زۀ لائق وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_27.mp3', '', 1761754199, 1761754199),
(42213, 'Job 33:28', 'Job', 33, 28, 'خُدائ پاک زۀ د قبر نه بچ کړم، او زما ژوند به په رڼا کښې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_28.mp3', '', 1761754199, 1761754199),
(42214, 'Job 33:29', 'Job', 33, 29, 'بې‌شکه چې دا د خُدائ پاک کارونه دى، او د انسان دپاره يې بار بار کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_29.mp3', '', 1761754199, 1761754199),
(42215, 'Job 33:30', 'Job', 33, 30, 'هغه يې د قبر نه بچ کوى، او د ژوند په خوند يې پوهوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_30.mp3', '', 1761754199, 1761754199),
(42216, 'Job 33:31', 'Job', 33, 31, 'ايُوبه، ما ته توجو شه او ما ته غوږ ونيسه، تۀ خاموش اوسه او زۀ به خبرې کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_31.mp3', '', 1761754199, 1761754199),
(42217, 'Job 33:32', 'Job', 33, 32, 'کۀ تۀ څۀ وائې، نو ووايه، زۀ غواړم چې تا بې‌ګناه ثابت کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_32.mp3', '', 1761754199, 1761754199),
(42218, 'Job 33:33', 'Job', 33, 33, 'کۀ داسې نۀ وى، نو ما ته غوږ ونيسه، خاموش شه او زۀ به تا ته د عقل ښودنه وکړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job33_verse_33.mp3', '', 1761754199, 1761754199),
(42219, 'Job 2:1', 'Job', 2, 1, 'يو ځل آسمانى مخلوق راغلو چې خپل ځانونه د مالِک خُدائ په مخکښې حاضر کړى او شېطان هم د هغوئ سره راغلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_1.mp3', '', 1761754199, 1761754199),
(42220, 'Job 2:2', 'Job', 2, 2, 'مالِک خُدائ شېطان ته وفرمائيل، ”تا څۀ کول؟“ نو شېطان ووئيل، ”زۀ په زمکه ګرځېدم راګرځېدم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_2.mp3', '', 1761754199, 1761754199),
(42221, 'Job 2:3', 'Job', 2, 3, 'نو مالِک خُدائ شېطان ته وفرمائيل، ”ستا زما د خِدمت کوونکى ايُوب په باره کښې څۀ خيال دے؟ په زمکه باندې د هغۀ په شان هيڅ څوک هم نشته، هغه يو بې‌داغه او نېک سړے دے چې هغه د خُدائ پاک نه يريږى او د بدۍ نه ځان ساتى. هغه تر اوسه پورې په خپل صداقت کښې قائم دے، اګر چې تا زۀ د هغۀ خِلاف لمسولم، چې بغېر د څۀ وجې نه يې په غضب آخته کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_3.mp3', '', 1761754199, 1761754199),
(42222, 'Job 2:4', 'Job', 2, 4, 'بيا شېطان مالِک خُدائ ته ووئيل، ”خلق د خپل ژوند بچ کولو دپاره هر څۀ ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_4.mp3', '', 1761754199, 1761754199),
(42223, 'Job 2:5', 'Job', 2, 5, 'خو کۀ د هغۀ په بدن باندې تکليف راولې، نو هغه به ستا په حضور کښې په تا لعنت ووائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_5.mp3', '', 1761754199, 1761754199),
(42224, 'Job 2:6', 'Job', 2, 6, 'نو مالِک خُدائ شېطان ته وفرمائيل، ”بلکل ټيک ده هغه ستا په اختيار کښې دے خو هغه ژوندے پرېږده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_6.mp3', '', 1761754199, 1761754199),
(42225, 'Job 2:7', 'Job', 2, 7, 'نو شېطان د مالِک خُدائ د حضور نه لاړو او په ايُوب باندې يې د سر نه تر پښو پورې خرابې دانې راوخېژولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_7.mp3', '', 1761754199, 1761754199),
(42226, 'Job 2:8', 'Job', 2, 8, 'نو ايُوب د خاورې د مات لوښى يوه ټوټه واخستله او ځان يې ورباندې ګرولو او په ايرو باندې کښېناستو چې خپل خفګان څرګند کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_8.mp3', '', 1761754199, 1761754199),
(42227, 'Job 2:9', 'Job', 2, 9, 'نو ايُوب ته خپلې ښځې ووئيل، ”تر اوسه پورې تۀ لا په خپل صداقت قائم يې؟ په خُدائ پاک لعنت ووايه او مړ شه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_9.mp3', '', 1761754199, 1761754199),
(42228, 'Job 2:10', 'Job', 2, 10, 'خو هغۀ خپلې ښځې ته وفرمائيل، ”تۀ خو لکه د کم عقلې ښځې په شان خبرې کوې، ولې مونږ به د خُدائ د طرفه صرف ښۀ څيزونه اخلو څۀ او هيڅکله به ترې نه بد نۀ اخلو؟“ خو د دې ټولو خبرو باوجود ايُوب د خُدائ پاک خِلاف يوه خبره هم ونۀ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_10.mp3', '', 1761754199, 1761754199),
(42229, 'Job 2:11', 'Job', 2, 11, 'نو چې کله د ايُوب درې ملګرى د هغه ټولو مصيبتونو نه خبر شول کوم چې په ايُوب باندې راغلى وُو، نو هغوئ هر يو د خپل خپل کور نه روان شول هغوئ په يو ځائ ايُوب له ورغلل چې د تسلۍ خبرې ورته وکړى. د هغوئ نومونه دا دى، اليفز تيمانى، بِلداد شوحى، او ضوفر نعماتى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_11.mp3', '', 1761754199, 1761754199),
(42230, 'Job 2:12', 'Job', 2, 12, 'کله چې هغوئ ايُوب د لرې نه وليدلو، نو هغه د پېژندګلو نه وتے وو خو چې کله يې وپېژندو نو په چغو چغو يې وژړل، هغوئ د غم نه خپلې چُوغې وشلولې او په سر باندې يې خاورې واچولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_12.mp3', '', 1761754199, 1761754199),
(42231, 'Job 2:13', 'Job', 2, 13, 'هغوئ د هغۀ سره په زمکه باندې اووۀ شپې او اووۀ ورځې ناست وُو او يو کس هم هغۀ ته يوه خبره هم ونۀ کړه، ځکه چې هغوئ ته پته وه چې د هغۀ تکليف ډېر زيات دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job2_verse_13.mp3', '', 1761754199, 1761754199),
(42232, 'Ecclesiastes 11:1', 'Ecclesiastes', 11, 1, 'خپلې دانې په لمده ځمکه کې وشینده ځکه څو ورځې وروسته به ته هغه بېرته حاصل کړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes11_verse_1.mp3', '', 1761754199, 1761754199),
(42233, 'Ecclesiastes 11:2', 'Ecclesiastes', 11, 2, 'د خپلو دانو یوه برخه له اوو اتو کسانو سره شریکې کړه ځکه ته نه پوهېږې چې په ځمکه باندې به څه افت راځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes11_verse_2.mp3', '', 1761754199, 1761754199),
(42234, 'Ecclesiastes 11:3', 'Ecclesiastes', 11, 3, 'که ورېځې نمجنې او درندې شي نو په ځمکه باندې باران وریږي او که ونه جنوب یا شمال لوري ته چپه شي نو په هماغه ځای به پرته وي چې پرې رالویږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes11_verse_3.mp3', '', 1761754199, 1761754199),
(42235, 'Ecclesiastes 11:4', 'Ecclesiastes', 11, 4, 'څوک چې د باد لوري ته ګوري هغه بیا څه نه کري او څوک چې ورېځو ته ګوري هغه بیا حاصل نه رېبي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes11_verse_4.mp3', '', 1761754199, 1761754199),
(42236, 'Ecclesiastes 11:5', 'Ecclesiastes', 11, 5, 'لکه څنګه چې ته نه پوهېږې چې باد له کوم ځایه لګیږي یا د امیدوارې ښځې په ګېډه کې ماشوم څرنګه لوییږي نو همدا شان ته د خدای په کارونو هم نه پوهېږې چې دا دواړه د هغه له خوا تر‌سره کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes11_verse_5.mp3', '', 1761754199, 1761754199),
(42237, 'Ecclesiastes 11:6', 'Ecclesiastes', 11, 6, 'په سهار کې خپل تخم وکره او په ماښام کې هم لاس تر زنې مه کښېنه ځکه ته نه پوهېږې چې په کوم کار کې بریالیتوب شته په دې کار کې یا په هغه بل کار کې یا په دواړو کې په برابره توګه بریالیتوب شته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes11_verse_6.mp3', '', 1761754199, 1761754199),
(42238, 'Ecclesiastes 11:7', 'Ecclesiastes', 11, 7, 'نو د لمر روښنایي څومره خوږه ده او د انسان دپاره څومره ښه ده چې د لمر د روښنایۍ لاندې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes11_verse_7.mp3', '', 1761754199, 1761754199),
(42239, 'Ecclesiastes 11:8', 'Ecclesiastes', 11, 8, 'په حقیقت کې، یو سړی چې ډېر کلونه عمر کوي هغه باید خوشحالي وکړي او له خپل ژوند نه خوند واخلي، خو هغه باید په یاد ولري چې د تیارې ورځې ډېرې زیاتې وي. نو هرڅه چې په راتلونکې کې پېښیږي هغه ټول لوګي او پوکي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes11_verse_8.mp3', '', 1761754199, 1761754199),
(42240, 'Ecclesiastes 11:9', 'Ecclesiastes', 11, 9, 'نو ای ځوانه! د ځوانۍ په ورځو کې خوشحالي وکړه او د خپل ځلمیتوب له هرې شېبې نه یې خوند واخله. چېرته چې ستا زړه ځي او سترګې دې ګوري هلته دې ستا پښې هم لاړې شي. خو په دې پوه شه چې خدای به ستا د زړه د ارمانونو او عملونو قضاوت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes11_verse_9.mp3', '', 1761754199, 1761754199),
(42241, 'Ecclesiastes 11:10', 'Ecclesiastes', 11, 10, 'له خپل زړه څخه غم او غوسه لېرې کړه او له خپل بدن څخه درد او کړاو وباسه، ځکه چې ځواني او د ځلمیتوب سباوون لوګی او پوکی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes11_verse_10.mp3', '', 1761754199, 1761754199),
(42242, 'Ezekiel 38:1', 'Ezekiel', 38, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_1.mp3', '', 1761754199, 1761754199),
(42243, 'Ezekiel 38:2', 'Ezekiel', 38, 2, '«ای فاني انسانه، خپل مخ دې د جوج خواته چې د ماجوج د هېواد څخه دی او د ماشک او توبال پاچا دی، واړوه او د هغه په ضد نبوت وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_2.mp3', '', 1761754199, 1761754199),
(42244, 'Ezekiel 38:3', 'Ezekiel', 38, 3, 'زه څښتن تعالی داسې وایم: ‹ګوره، ای جوجه، د ماشک او توبال پاچا، زه ستا دښمن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_3.mp3', '', 1761754199, 1761754199),
(42245, 'Ezekiel 38:4', 'Ezekiel', 38, 4, 'زه به تا راوګرځوم، ستا په ژامو کې به چنګکونه واچوم او تا به د خپلو ټولو لښکرو، اسونو او سپرو عسکرو سره چې شمېر یې ډېر زیات دی او ټول په زغرو، وړو او لویو سپرونو او تورو باندې سمبال دي، راوباسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_4.mp3', '', 1761754199, 1761754199),
(42246, 'Ezekiel 38:5', 'Ezekiel', 38, 5, 'د هغوی سره به د فارس، ایتوپیا او لیبیا لښکرې وي چې د هغوی ټولو سره به سپرونه او د زغرو خولۍ‌ګانې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_5.mp3', '', 1761754199, 1761754199),
(42247, 'Ezekiel 38:6', 'Ezekiel', 38, 6, 'د جومر او د شمال د لېرې ځای نه د بیت‌توجرمه د وطنونو څخه به ټول جنګیالي د هغه سره وي، یعنې د ډېرو قومونو سړي به ورسره وي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_6.mp3', '', 1761754199, 1761754199),
(42248, 'Ezekiel 38:7', 'Ezekiel', 38, 7, 'هغه ته ووایه: ‹تیار اوسه، ته او ستا ټولې شاوخوا لښکرې باید ستا تر قوماندې لاندې تیاری ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_7.mp3', '', 1761754199, 1761754199),
(42249, 'Ezekiel 38:8', 'Ezekiel', 38, 8, 'له ډېرو کلونو وروسته به زه تاته حکم درکړم چې په اسراییلو باندې حمله وکړې. دا به داسې هېواد وي چې خلک یې د جنګ نه وروسته ځای په ځای شوي وي. خلک به یې د ډېرو قومونو څخه راټول شوي وي او په هغو غرونو کې به واوسیږي چې ډېره موده وران او ویجاړ پراته وو. هغه وخت به هغوی ټول په امن کې ژوند تېر کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_8.mp3', '', 1761754199, 1761754199),
(42250, 'Ezekiel 38:9', 'Ezekiel', 38, 9, 'ته او ستا لښکر او ستا سره نور ډېر قومونه به لکه د توفان په شان حمله وکړئ او هغه وطن به لکه د ورېځې په شان پټ کړئ.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_9.mp3', '', 1761754199, 1761754199),
(42251, 'Ezekiel 38:10', 'Ezekiel', 38, 10, 'څښتن تعالی جوج ته داسې وایي: ‹کله چې هغه وخت راورسیږي، نو ستا ذهن ته به بد فکرونه راشي او یوه ناوړه نقشه به جوړه کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_10.mp3', '', 1761754199, 1761754199),
(42252, 'Ezekiel 38:11', 'Ezekiel', 38, 11, 'د ځان سره به ووایې چې په یو داسې بې‌وزله وطن باندې حمله کوم چې خلک یې په داسې ښارګوټو کې په امن او ارامۍ سره ژوند تېروي چې نه دېوالونه لري، نه دروازې او نه اړمونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_11.mp3', '', 1761754199, 1761754199),
(42253, 'Ezekiel 38:12', 'Ezekiel', 38, 12, 'ته به هغه خلک لوټ او تالا کړې چې په داسې ښارونو کې اوسیږي چې یو وخت وران پراته وو. هغوی د نورو قومونو نه راټول شوي، اوس د څارویو او د مال او جایداد خاوندان دي او د نړۍ د سوداګرۍ په مرکز کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_12.mp3', '', 1761754199, 1761754199),
(42254, 'Ezekiel 38:13', 'Ezekiel', 38, 13, 'د شیبا او ددان خلک او د ترشیش د ښار سوداګران به ستا نه پوښتنه کوي: ”ایا تا خپل لښکر راټول کړی چې د لوټ او تالان په خاطر حمله وکړې؟ ایا دا نیت لرې چې سپین زر، سره زر، څاروي او ډېره شتمني په غنیمت یوسئ؟“›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_13.mp3', '', 1761754199, 1761754199),
(42255, 'Ezekiel 38:14', 'Ezekiel', 38, 14, 'نو په دې خاطر ای فاني انسانه، نبوت وکړه او جوج ته ووایه چې څښتن تعالی داسې وایي: ‹کله چې ته ووینې چې زما قوم په امن کې ژوند تېروي، نو راویښ به شې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_14.mp3', '', 1761754199, 1761754199),
(42256, 'Ezekiel 38:15', 'Ezekiel', 38, 15, 'ته به د خپل ځای نه چې لېرې په شمال کې دی، د خپل لوی او قوي لښکر سره چې د ډېرو قومونو د عسکرو نه جوړ شوی دی او ټول به په اسونو باندې سپاره وي، راشې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_15.mp3', '', 1761754199, 1761754199),
(42257, 'Ezekiel 38:16', 'Ezekiel', 38, 16, 'تاسو به زما په قوم اسراییلو باندې داسې حمله کوئ، لکه ځمکه چې ورېځ پټوي. په وروستیو ورځو کې به زه تا ولېږم چې زما په وطن باندې حمله وکړې، ترڅو ای جوجه، قومونه په دې پوه شي چې زه څوک یم او ستا په وسیله به خپل سپېڅلتوب وښایم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_16.mp3', '', 1761754199, 1761754199),
(42258, 'Ezekiel 38:17', 'Ezekiel', 38, 17, '«څښتن تعالی داسې وایي: ‹ایا ته هغه څوک یې چې ډېر پخوا مې ستا په هکله خبرې کړې وې؟ هغه وخت ما د خپلو خدمتګارانو یعنې د اسراییلو د نبیانو په وسیله ویلي وو. هغوی تر ډېرو کلونو پورې پېشګویي کوله چې په راتلونکو ورځو کې به زه یو کس په اسراییلو باندې د حملې دپاره راولم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_17.mp3', '', 1761754199, 1761754199),
(42259, 'Ezekiel 38:18', 'Ezekiel', 38, 18, 'څښتن تعالی وایي: ‹په هماغه ورځ چې جوج په اسراییلو باندې حمله وکړي، نو زه به سخت په قهر یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_18.mp3', '', 1761754199, 1761754199),
(42260, 'Ezekiel 38:19', 'Ezekiel', 38, 19, 'زه په خپل غیرت او په سخت قهر کې اعلان کوم چې په هغه ورځ به د اسراییلو په وطن کې سخته زلزله وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_19.mp3', '', 1761754199, 1761754199),
(42261, 'Ezekiel 38:20', 'Ezekiel', 38, 20, 'ټول ماهیان او مرغان، ټول لوی حیوانات، خزندې او د ځمکې په مخ ټول انسانان به زما په حضور کې ولړزیږي. غرونه به راوغورځول شي، کمرې به ونړیږي او ټول دېوالونه به راچپه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_20.mp3', '', 1761754199, 1761754199),
(42262, 'Ezekiel 38:21', 'Ezekiel', 38, 21, 'زه به په خپلو ټولو غرونو کې د جوج په ضد جنګ راولم، ما څښتن تعالی داسې ویلي دي. د هغه عسکر به په خپلو کې یو بل په تورو باندې ووهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_21.mp3', '', 1761754199, 1761754199),
(42263, 'Ezekiel 38:22', 'Ezekiel', 38, 22, 'زه به هغه په وبا او وینې تویولو سره محاکمه او هغه ته به سزا ورکړم. زه به په هغه او د هغه په لښکرو او نورو ډېرو قومونو باندې چې د هغه په خوا ولاړ دي، د باران توفان او ږلۍ د اور او ګوګړو سره نازل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_22.mp3', '', 1761754199, 1761754199),
(42264, 'Ezekiel 38:23', 'Ezekiel', 38, 23, 'په دې ډول به زه ډېرو قومونو ته وښایم چې زه ډېر لوی او سپېڅلی ذات یم. نو بیا به هغوی پوه شي چې زه څښتن یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel38_verse_23.mp3', '', 1761754199, 1761754199),
(42265, 'Isaiah 4:1', 'Isaiah', 4, 1, 'کله چې هغه ورځ راشي، نو اووه ښځې به د یو سړي لمن ونیسي او ورته به ووایي: «مونږ په خپله د خپلو ځانونو دپاره خوراک او کالي تیاروو، یوازې غواړو چې ته زمونږ مېړه اوسې، ترڅو له دې شرمه وژغورل شو چې مونږ واده شوې نه یو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah4_verse_1.mp3', '', 1761754199, 1761754199),
(42266, 'Isaiah 4:2', 'Isaiah', 4, 2, 'هغه ورځ راتلونکې ده چې څښتن به د دې وطن هر بوټی او ونه لویه او ښایسته کړي او هغه حاصلات چې ځمکه یې ورکوي هغه به د هغو ټولو اسراییلیانو دپاره چې ژوندي پاتې کیږي، د ویاړ او عزت سبب شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah4_verse_2.mp3', '', 1761754199, 1761754199),
(42267, 'Isaiah 4:3', 'Isaiah', 4, 3, 'هغه خلک چې په صهیون کې پاتې شوي دي او لیکل شوي دي چې په اورشلیم کې به ژوندي واوسي، نو هغوی به سپېڅلي وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah4_verse_3.mp3', '', 1761754199, 1761754199),
(42268, 'Isaiah 4:4', 'Isaiah', 4, 4, 'له دې نه مخکې به څښتن د اسراییلو د قوم په هکله قضاوت وکړي او هغه به پاک کړي او د اورشلیم ګناهونه او هغه وینه چې هلته توی شوې ده، هغه به ووینځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah4_verse_4.mp3', '', 1761754199, 1761754199),
(42269, 'Isaiah 4:5', 'Isaiah', 4, 5, 'بیا به څښتن د صهیون په غره باندې او په هغو ټولو خلکو باندې چې په هغه ځای کې راټولیږي، د ورځې له خوا ورېځ او د شپې له خوا به ورباندې لوګی او د اور ځلېدونکې لمبې نازلې کړي. دا به د دې جلالي ځای دپاره یو پوښ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah4_verse_5.mp3', '', 1761754199, 1761754199),
(42270, 'Isaiah 4:6', 'Isaiah', 4, 6, 'د هغه جلال به په ښار باندې د جونګړې په شان سیوری جوړ کړي چې د ورځې له ګرمۍ نه او همدارنګه د توفان او باران څخه یې خوندي وساتي او د هغه څخه به د امن ځای جوړ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah4_verse_6.mp3', '', 1761754199, 1761754199),
(42271, 'Isaiah 34:1', 'Isaiah', 34, 1, 'ای د ټولو قومونو خلکو، نژدې راشئ او غوږ ونیسئ. ای د نړۍ ټولو خلکو واورئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_1.mp3', '', 1761754199, 1761754199),
(42272, 'Isaiah 34:2', 'Isaiah', 34, 2, 'ځکه څښتن په ټولو قومونو او د هغوی په لښکرو ډېر په قهر دی. هغوی به په مرګ محکوم او ټول به حلال کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_2.mp3', '', 1761754199, 1761754199),
(42273, 'Isaiah 34:3', 'Isaiah', 34, 3, 'د هغوی مړي به نه ښخیږي، د خوسا شویو مړو بوی به ټوله ځمکه ونیسي او د هغوی وینې به د غرونو نه جاري شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_3.mp3', '', 1761754199, 1761754199),
(42274, 'Isaiah 34:4', 'Isaiah', 34, 4, 'لمر، سپوږمۍ او ستوري به خواره واره او فنا شي. اسمان به لکه د طومار په شان تاو او راتاو شي او ستوري به داسې راولویږي لکه څنګه چې د انګورو د تاک څخه وچې پاڼې او د انځرو د ونو څخه وچ انځر رالویږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_4.mp3', '', 1761754199, 1761754199),
(42275, 'Isaiah 34:5', 'Isaiah', 34, 5, 'د څښتن تورې خپل کار په اسمان کې سر ته رسولی دی او اوس به د ادوم په خلکو ګوزار وکړي، یعنې هغه خلک چې څښتن په نابودۍ محکوم کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_5.mp3', '', 1761754199, 1761754199),
(42276, 'Isaiah 34:6', 'Isaiah', 34, 6, 'د هغه توره به په وینو رنګ او په وازګو کې پټه وي، یعنې د وریو او وزو په وینو او همدارنګه د پسونو د پښتورګو په وازګو کې. هو، څښتن به د ادوم د هېواد او د بزرې په ښار کې ډېر خلک لکه د قربانۍ په شان حلال کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_6.mp3', '', 1761754199, 1761754199),
(42277, 'Isaiah 34:7', 'Isaiah', 34, 7, 'حتی هغه خلک به هم مړه شي چې د ځنګلي غویانو او سخوندرانو په شان قوي دي. ځمکه به په وینو خړوبه او په وازګو به پټه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_7.mp3', '', 1761754199, 1761754199),
(42278, 'Isaiah 34:8', 'Isaiah', 34, 8, 'ځکه څښتن له دښمنانو څخه د بدل د اخیستلو ورځ او د صهیون د تاوان ورکولو دپاره یې کال ټاکلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_8.mp3', '', 1761754199, 1761754199),
(42279, 'Isaiah 34:9', 'Isaiah', 34, 9, 'د ادوم سیندونه به د قیر څخه ډک او خاوره به یې په ګوګړو بدله شي او ټول وطن به د قیر په شان وسوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_9.mp3', '', 1761754199, 1761754199),
(42280, 'Isaiah 34:10', 'Isaiah', 34, 10, 'ادوم به شپه او ورځ سوځي او تل به ورڅخه لوګی پورته کیږي. هغه وطن به له یو نسله تر بل نسله پورې وران وي او نور به هېڅوک له هغه ځایه تېر نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_10.mp3', '', 1761754199, 1761754199),
(42281, 'Isaiah 34:11', 'Isaiah', 34, 11, 'کونګیان او کارغان به هغه هېواد ونیسي او هغوی به په کې واوسیږي، ځکه څښتن اراده لري چې ادوم له منځه یوسي او هغه شاړ او خالي پرېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_11.mp3', '', 1761754199, 1761754199),
(42282, 'Isaiah 34:12', 'Isaiah', 34, 12, 'د اشرافو څخه به هېڅوک ژوندی پاتې نه شي، ترڅو پاچا شي او ټول مشران به له منځه لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_12.mp3', '', 1761754199, 1761754199),
(42283, 'Isaiah 34:13', 'Isaiah', 34, 13, 'په ټولو ماڼیو او دېوال لرونکو ښارونو کې به اغزي راشنه شي او سورلنډیان او کونګیان به په کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_13.mp3', '', 1761754199, 1761754199),
(42284, 'Isaiah 34:14', 'Isaiah', 34, 14, 'په ادوم کې به د صحرا حیوانات د لېوانو سره قدم وهي او د وزانو په شکل پېریان به په کې یو بل ته نارې وهي. همدارنګه د مرغۍ په شان دېوان به د شپې په وخت هلته ځي چې د ارام کولو دپاره ځای پیدا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_14.mp3', '', 1761754199, 1761754199),
(42285, 'Isaiah 34:15', 'Isaiah', 34, 15, 'کونګیان به په ادوم کې خپلې ځالې جوړوي، هګۍ به په کې اچوي، بچي به ورنه وباسي او د خپلو بچیو ساتنه به کوي. هلته به د باښو جوړې هم راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_15.mp3', '', 1761754199, 1761754199),
(42286, 'Isaiah 34:16', 'Isaiah', 34, 16, 'د څښتن کلام ولټوئ او ولولئ، ترڅو پوه شئ چې د هغه ټولې پېشګویۍ عملي کیږي. ټول وحشي حیوانات او مرغان به حاضر وي او هېڅ یو به بې جوړې نه وي. ځکه څښتن په خپله دا ویلي دي او د هغه روح به هغوی راټول کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_16.mp3', '', 1761754199, 1761754199),
(42287, 'Isaiah 34:17', 'Isaiah', 34, 17, 'دا څښتن دی چې د ادوم اندازه یې معلومه کړې ده او حیوانات او مرغان یې په کې وېشلي دي، ترڅو هغه هېواد تل د هغوی شي او نسل په نسل په هغه کې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah34_verse_17.mp3', '', 1761754199, 1761754199),
(42288, 'Job 40:1', 'Job', 40, 1, 'بيا مالِک خُدائ ايُوب ته وفرمائيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_1.mp3', '', 1761754199, 1761754199),
(42289, 'Job 40:2', 'Job', 40, 2, '”تۀ اوس هم د قادر خُدائ سره بحث کول غواړې څۀ؟ څوک چې د خُدائ پاک سره بحث کوى نو هغه به جواب ورکوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_2.mp3', '', 1761754199, 1761754199),
(42290, 'Job 40:3', 'Job', 40, 3, 'بيا ايُوب مالِک خُدائ له جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_3.mp3', '', 1761754199, 1761754199),
(42291, 'Job 40:4', 'Job', 40, 4, '”ګوره، زۀ هيڅ هم نۀ يم، زۀ به تا له څۀ جواب درکړم؟ زۀ په خپله خولۀ باندې لاس ږدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_4.mp3', '', 1761754199, 1761754199),
(42292, 'Job 40:5', 'Job', 40, 5, 'ما ډېر څۀ وئيلى دى، نور زۀ څۀ نۀ وايم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_5.mp3', '', 1761754199, 1761754199),
(42293, 'Job 40:6', 'Job', 40, 6, 'بيا مالِک خُدائ د طوفان نه ايُوب له جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_6.mp3', '', 1761754199, 1761754199),
(42294, 'Job 40:7', 'Job', 40, 7, '”نو اوس ورته ټينګ شه، زۀ به ستا نه تپوس وکړم او تۀ به ما له جواب راکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_7.mp3', '', 1761754199, 1761754199),
(42295, 'Job 40:8', 'Job', 40, 8, 'ولې تۀ د دې ثابِتولو کوشش کوې چې زۀ بې‌اِنصافه يم، او ما غلط وګڼې او خپل ځان ته صحيح ووائې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_8.mp3', '', 1761754199, 1761754199),
(42296, 'Job 40:9', 'Job', 40, 9, 'تۀ د خُدائ پاک په شان تکړه يې څۀ، ستا آواز د هغۀ د تندر د آواز په شان کېدے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_9.mp3', '', 1761754199, 1761754199),
(42297, 'Job 40:10', 'Job', 40, 10, 'کۀ داسې وى نو په رُعب داب او شان و شوکت سره خپل ځان سنګار کړه، د عزت او درناوى په جامو باندې خپل ځان پټ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_10.mp3', '', 1761754199, 1761754199),
(42298, 'Job 40:11', 'Job', 40, 11, 'خپل ځان په قهر کړه، هر يو مغرور سړى ته ګوره او هغه سپک کړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_11.mp3', '', 1761754199, 1761754199),
(42299, 'Job 40:12', 'Job', 40, 12, 'ټولو مغروره خلقو ته وګوره او هغوئ عاجزان کړه، او بدعمله خلق ټک سره ووژنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_12.mp3', '', 1761754199, 1761754199),
(42300, 'Job 40:13', 'Job', 40, 13, 'هغوئ ټول په خاورو کښې ښخ کړه، او هغوئ قبر کښې قېد کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_13.mp3', '', 1761754199, 1761754199),
(42301, 'Job 40:14', 'Job', 40, 14, 'نو زۀ به دې هم صِفت وکړم، ځکه چې خپل طاقت تا بچ کولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_14.mp3', '', 1761754199, 1761754199),
(42302, 'Job 40:15', 'Job', 40, 15, 'دريابى مېښې ته وګوره، چې هغه مې هم هغه شان جوړه کړې ده لکه څنګه مې چې تۀ جوړ کړے يې، دا د يو غوَيى په شان واښۀ خورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_15.mp3', '', 1761754199, 1761754199),
(42303, 'Job 40:16', 'Job', 40, 16, 'د هغې طاقت د هغې په بدن کښې دے، او د هغې طاقت د هغې د خېټې په پټو کښې دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_16.mp3', '', 1761754199, 1761754199),
(42304, 'Job 40:17', 'Job', 40, 17, 'د هغې لکۍ لکه د دِيار د ونې په شان سخته ده، د هغې د پتُون پټې خپلو کښې غوټه شوې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_17.mp3', '', 1761754199, 1761754199),
(42305, 'Job 40:18', 'Job', 40, 18, 'د دې هډوکى د زېړو نلکې دى، د هغې هډوکى د اوسپنې سيخونه دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_18.mp3', '', 1761754199, 1761754199),
(42306, 'Job 40:19', 'Job', 40, 19, 'دا د خُدائ پاک د کارنامو يو لوئ کار دے، او صرف د دې خالِق په دې باندې قابو موندلے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_19.mp3', '', 1761754199, 1761754199),
(42307, 'Job 40:20', 'Job', 40, 20, 'ځکه چې غرونه د دې دپاره خوراک پېدا کوى چرته چې ټول ځنګلى ځناور لوبې کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_20.mp3', '', 1761754199, 1761754199),
(42308, 'Job 40:21', 'Job', 40, 21, 'دا په اوبو کښې د نيلوفر بوټو لاندې پراتۀ وى او د لوخې په ډنډونو کښې پټ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_21.mp3', '', 1761754199, 1761754199),
(42309, 'Job 40:22', 'Job', 40, 22, 'د نيلوفر بوټى ورباندې سورے کوى، او د نِهر د غاړې د وَلو ونې د دې نه ګېرچاپېره تاو وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_22.mp3', '', 1761754199, 1761754199),
(42310, 'Job 40:23', 'Job', 40, 23, 'کۀ سيند په موج کښې وى، نو دا نۀ يريږى، د اُردن سيند کۀ تر خولې پورې هم ډک وى نو دا نۀ يريږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_23.mp3', '', 1761754199, 1761754199);